import fs from "fs";
import path from "path";
export const mockSchema = {
    parse: (args) => ({
        apiPattern: args?.apiPattern || "**/api/**",
        scenario: args?.scenario || "happy_path",
        outputPath: args?.outputPath || "mocks/api.mocks.ts",
        ...args
    })
};
export async function mockTool(input) {
    const mockContent = `// Auto-generated by playwright-mcp-autonomous-agent
import { Page } from '@playwright/test';
export const mock3MData = {
  totalViews: "3M+",
  metrics: [
    { name: "Product Health", value: 85, trend: "up" },
    { name: "Team Velocity", value: 92, trend: "stable" }
  ],
  quarterComparison: { current: "Q1 2026", previous: "Q4 2025", change: "+12%" }
};
export async function setupMocks(page) {
  await page.route('${input.apiPattern}', async route => {
    const url = route.request().url();
    if (url.includes('/dashboard')) {
      await route.fulfill({ json: mock3MData });
    } else {
      await route.continue();
    }
  });
}
`;
    const dir = path.dirname(input.outputPath);
    if (!fs.existsSync(dir))
        fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(input.outputPath, mockContent);
    return {
        content: [{ type: "text", text: `✅ Created mock file at ${input.outputPath}` }]
    };
}